-- All of March, including 23:59:59.9999999 on the 31st
SELECT * FROM payments
WHERE created_at >= '2026-03-01' AND created_at < '2026-04-01';

-- BUG: misses everything after midnight on March 31
SELECT * FROM payments
WHERE created_at BETWEEN '2026-03-01' AND '2026-03-31';

-- BUG: a function on the column prevents an index seek
SELECT * FROM payments WHERE YEAR(created_at) = 2026;
